#!/usr/bin/env python3
"""Patch the Android project generated by `flutter create` (Groovy or Kotlin DSL)."""
import pathlib, re, shutil, sys

root = pathlib.Path(sys.argv[1] if len(sys.argv) > 1 else "app")
android = root / "android"
app = android / "app"
here = pathlib.Path(__file__).parent

# Manifest: internet, label, tel: intent visibility
mf = app / "src/main/AndroidManifest.xml"
m = mf.read_text()
if "permission.INTERNET" not in m:
    m = m.replace("<application", '<uses-permission android:name="android.permission.INTERNET"/>\n    <application', 1)
m = re.sub(r'android:label="[^"]*"', 'android:label="Marine Ops"', m, count=1)
q = """<queries>
        <intent><action android:name="android.intent.action.DIAL"/><data android:scheme="tel"/></intent>
        <intent><action android:name="android.intent.action.VIEW"/><data android:scheme="tel"/></intent>
        <intent><action android:name="android.intent.action.VIEW"/><data android:scheme="https"/></intent>"""
if "<queries>" in m:
    m = m.replace("<queries>", q, 1)
else:
    m = m.replace("</manifest>", q + "\n    </queries>\n</manifest>", 1)
mf.write_text(m)

# Fixed signing key so new versions install over old ones
shutil.copy(here / "release.jks", app / "release.jks")
kts = (app / "build.gradle.kts").exists()
bf = app / ("build.gradle.kts" if kts else "build.gradle")
g = bf.read_text()
g = re.sub(r"minSdk\s*=\s*flutter\.minSdkVersion", "minSdk = 23", g)
g = re.sub(r"minSdkVersion\s+flutter\.minSdkVersion", "minSdkVersion 23", g)
g = re.sub(r"ndkVersion\s*=\s*flutter\.ndkVersion", 'ndkVersion = "27.0.12077973"', g)
if kts:
    g = re.sub(r"buildTypes\s*\{", '''signingConfigs {
        create("release") {
            storeFile = file("release.jks")
            storePassword = "marineops2026"
            keyAlias = "marine"
            keyPassword = "marineops2026"
        }
    }
    buildTypes {''', g, count=1)
    g = g.replace('signingConfig = signingConfigs.getByName("debug")', 'signingConfig = signingConfigs.getByName("release")')
else:
    g = re.sub(r"buildTypes\s*\{", '''signingConfigs {
        release {
            storeFile file("release.jks")
            storePassword "marineops2026"
            keyAlias "marine"
            keyPassword "marineops2026"
        }
    }
    buildTypes {''', g, count=1)
    g = g.replace("signingConfig = signingConfigs.debug", "signingConfig = signingConfigs.release")
bf.write_text(g)

# Toolchain (same versions proven in the KOC ONE build)
for name in ("settings.gradle", "settings.gradle.kts"):
    p = android / name
    if p.exists():
        s = p.read_text()
        s = re.sub(r'(id\s*\(?\s*"com\.android\.application"\s*\)?\s*version\s*)"[^"]+"', r'\g<1>"8.7.3"', s)
        s = re.sub(r'(id\s*\(?\s*"org\.jetbrains\.kotlin\.android"\s*\)?\s*version\s*)"[^"]+"', r'\g<1>"2.1.0"', s)
        p.write_text(s)
wp = android / "gradle/wrapper/gradle-wrapper.properties"
wp.write_text(re.sub(r"gradle-[\d.]+-(all|bin)\.zip", "gradle-8.12-all.zip", wp.read_text()))

# Launcher icons
res = here / "res"
for f in res.rglob("*.png"):
    out = app / "src/main/res" / f.relative_to(res)
    out.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy(f, out)
print("patched", bf.name)
